    """
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0):
        super().__init__()
        self.avg_pool = nn.AvgPool3d(kernel_size=kernel_size, stride=stride, padding=padding)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies Average Pooling to the input tensor using custom CUDA operators for FP32 precision.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, channels, depth, height, width).

        Returns:
            torch.Tensor: Output tensor with Average Pooling applied, shape depends on kernel_size, stride and padding.
        """
        # Custom CUDA operator for average pooling
        def custom_avg_pool_kernel(input_tensor, kernel_size, stride, padding):
            """
            Kernel to perform average pooling over the spatial dimensions (height, width) 
            while keeping channels and depth unchanged. 

            Args:
                input_tensor: Input tensor of shape (batch_size, channels, depth, height, width).
                kernel_size: Size of the kernel to apply pooling.
                stride: Stride of the pooling operation.
                padding: Padding to apply before pooling.

            Returns:
                torch.Tensor: Pooled output tensor.
            """
            # Calculate spatial dimensions after pooling
            height = input_tensor.shape[3]
            width = input_tensor.shape[4]

            # Determine new spatial dimensions
            new_height = (height + 2 * padding - kernel_size) // stride
            new_width = (width + 2 * padding - kernel_size) // stride

            # Create output tensor with zeros
            out = torch.zeros_like(input_tensor)

            # Calculate number of blocks and threads
            block_size = max(1, kernel_size)
            num_blocks = (new_height + block_size - 1) // block_size
            num_threads = (new_width + block_size - 1) // block_size

            # Launch kernel
