                input_tensor.data_ptr<float>(), 
                torch.zeros_like(input_tensor).data_ptr<float>() * (new_height * new_width), 
                out.data_ptr<float>(), 
                new_height * new_width
            )

            return out

        # Define the custom CUDA kernel for average pooling
        elementwise_add_kernel = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void avg_pool_kernel(const float* input, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float sum = 0.0f;
        for (int i = 0; i < kernel_size; i++) {
            sum += input[idx + i];
        }
        out[idx] = sum / kernel_size;
    }
}

torch::Tensor custom_avg_pool_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    avg_pool_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

